let forecastKey='DO',forecastHours=48,forecastRate=0,forecastAllowSuspect=false,forecastResult=null,forecastEvaluation=null;
const evaluationCache={};
function forecastPlot(result){const pts=result.points,W=840,H=310,L=55,R=18,T=18,B=42;const low=Math.min(...pts.map(p=>Math.min(p.baseP10,p.scenarioP10))),high=Math.max(...pts.map(p=>Math.max(p.baseP90,p.scenarioP90)));const pad=(high-low)*.12||.2,lo=low-pad,hi=high+pad;const x=h=>L+h/result.hours*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);const line=k=>pts.map((p,i)=>(i?'L':'M')+x(p.hours).toFixed(2)+','+y(p[k]).toFixed(2)).join('');const band=pts.map((p,i)=>(i?'L':'M')+x(p.hours).toFixed(2)+','+y(p.scenarioP90).toFixed(2)).join('')+pts.slice().reverse().map(p=>'L'+x(p.hours).toFixed(2)+','+y(p.scenarioP10).toFixed(2)).join('')+'Z';let grid='';for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;grid+=`<line class="grid" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${f(v,2)}</text>`}for(let h=0;h<=result.hours;h+=6){grid+=`<text x="${x(h)}" y="${H-18}" text-anchor="middle">+${h}h</text>`}return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Simulation trajectory ${result.hours} hours"><path d="${band}" fill="#f2c77a" opacity=".25"/>${grid}<path d="${line('base')}" fill="none" stroke="#168572" stroke-width="2.3"/><path d="${line('scenario')}" fill="none" stroke="#bf8230" stroke-width="2" stroke-dasharray="6 4"/></svg></div><div class="chart-caption"><span><i></i>Historical-data baseline</span><span style="color:#af792e">┄ Assumed scenario</span><span>P10–P90 simulation band; not probability-calibrated</span></div>`}
function evaluationHTML(ev){return `<div class="table-wrap"><table><thead><tr><th>Horizon</th><th>Evaluation origins</th><th>Simulation MAE</th><th>Persistence MAE</th><th>Comparison</th></tr></thead><tbody>${[24,48].map(h=>{const m=ev.metrics[h];return `<tr><td>${h} hours</td><td>${m.count}</td><td>${f(m.simulationMAE,3)}</td><td>${f(m.persistenceMAE,3)}</td><td>${!m.count?'Insufficient data':m.simulationMAE<m.persistenceMAE?'Lower error on this test set':'Does not outperform benchmark'}</td></tr>`}).join('')}</tbody></table></div><p class="section-note">Rolling-origin: fit only the preceding seven days. Compare QC-passed targets within 10 minutes of +24/+48h. Few, overlapping origins; no independent validation or demonstrated field benefit.</p>`}
function forecastOutput(){if(!forecastResult)return '<div class="empty">Select a parameter and forecast origin, then run the simulation.</div>';if(!forecastResult.ok)return `<div class="notice warn">${esc(forecastResult.reason)}</div>`;const r=forecastResult,last=r.points.at(-1),range=problemSettings[r.key];let crossing=null;if(range)crossing=r.points.find(p=>p.hours>0&&(p.scenario<range.low||p.scenario>range.high));return `<div class="notice warn"><span>◇</span><div><strong>Research results under assumptions.</strong> The trajectory band is not a validated prediction interval. Weather, currents, biomass and equipment effects are not modeled. The five parameters are simulated independently, without coupled interactions.</div></div>${r.warnings.map(w=>`<p class="annotation">${esc(w)}</p>`).join('')}<div class="problem-summary"><div class="card"><span class="label">BASELINE AT ${r.hours} HOURS</span><div class="problem-reading">${f(last.base)}<small>${data.params[r.key].unit}</small></div><p class="section-note">Central statistical-model estimate</p></div><div class="card"><span class="label">SCENARIO AT ${r.hours} HOURS</span><div class="problem-reading">${f(last.scenario)}<small>${data.params[r.key].unit}</small></div><p class="section-note">Assumed additional change ${f(r.ratePerDay)} ${data.params[r.key].unit||'pH'}/day</p></div><div class="card"><span class="label">TRAJECTORY BAND AT THE ENDPOINT</span><h3 style="margin-top:19px">${f(last.scenarioP10)} – ${f(last.scenarioP90)}</h3><p class="section-note">P10–P90, not a probability of fish safety</p></div></div>${forecastPlot(r)}<div class="divider"></div><div class="two-col"><div><h3>Review guidance</h3><p class="small-copy">${crossing?`The scenario leaves the trial range at approximately +${f(crossing.hours,1)} hours. Arrange a cross-check before this hypothetical time and verify against farm-approved limits.`:range?'The central path stays within the trial range in this scenario. This does not guarantee that every trajectory or real condition remains within limits.':'No reference range is set: results describe trends, not species-specific water suitability.'}</p><p class="small-copy">${problems[r.key].steps.map((s,i)=>`${i+1}. ${s}`).join('<br>')}</p></div><div><h3>Run provenance</h3><p class="small-copy">Origin: ${date(r.sourceTime)} (UTC+7).<br>End: ${date(last.ts)}.<br>${r.training.samples} QC-passed samples, ${r.training.pairs} pairs; window ${date(r.training.start)} → ${date(r.training.end)}.<br>Model: ${r.modelVersion} · ${r.paths} trajectories · seed ${r.seed}.<br>State kind: simulated. Observed states and the Thing are not overwritten.</p></div></div><div class="form-actions"><button class="button secondary" id="exportLongForecast">↓ Export run JSON</button></div>`}
function forecastPage(){return heading('SIMULATION FORECAST / 24–48 HOURS','How might water conditions change over the next 1–2 days?','Initialize from the selected snapshot, simulate a baseline and compare an assumed additional trend.',`<button class="button secondary" data-go="overview">← Overview</button>`)+`<div class="notice"><span>ⓘ</span><div>Forecast origin <strong>${date(row().ts)} (UTC+7)</strong> is a historical observation, not a live reading today. The 24/48-hour horizon starts at that origin. Old inputs must not be presented as a current forecast.</div></div>`+frame('Choose simulation conditions',`<form id="longForecastForm"><div class="form-grid"><div class="field"><label for="longForecastKey">Parameter</label><select id="longForecastKey">${Object.keys(problems).map(k=>`<option value="${k}" ${forecastKey===k?'selected':''}>${problems[k].short} (${data.params[k].unit||'pH'})</option>`).join('')}</select></div><div class="field"><label for="longForecastHours">Horizon</label><select id="longForecastHours"><option value="24" ${forecastHours===24?'selected':''}>24 hours — 1 day</option><option value="48" ${forecastHours===48?'selected':''}>48 hours — 2 days</option></select></div><div class="field"><label for="longForecastRate">Additional scenario trend (${data.params[forecastKey].unit||'pH'}/day)</label><input id="longForecastRate" type="number" step="any" value="${forecastRate}" required><span class="section-note">0 means no additional assumed trend. This is not an equipment-response estimate.</span></div><div class="field"><label>Initialization and consistency</label><span class="small-copy">${f(row().values[forecastKey])} ${data.params[forecastKey].unit} · ${C.flagNames[C.qcAt(data.rows,cursor,forecastKey,cursor).flag]}<br>Fit only data before the origin, up to seven days.</span></div></div><label class="checkbox"><input type="checkbox" id="longForecastAllow" ${forecastAllowSuspect?'checked':''}> Accept a suspect reading as a hypothetical initial condition (not failed/missing readings)</label><div class="form-actions"><button type="submit" class="button">▷ Simulate ${forecastHours} hours</button><button type="button" class="button secondary" id="evaluateLongForecast">Evaluate historical 24/48h errors</button></div></form>`+timeline(),'Change the origin with the replay slider. Previous results are cleared when the initial snapshot changes.')+frame('Future scenario trajectories',forecastOutput())+(forecastEvaluation?frame('Horizon-specific historical evaluation',evaluationHTML(forecastEvaluation)): '')+frame('Model and limitations',`<p class="small-copy">Research model: least-squares 24h sine/cosine cycle with AR(1) residual memory. Historical innovations are resampled every 15 minutes to generate 120 trajectories. The same snapshot, seed and assumptions reproduce the result. Scenario trends are added over time; physical causes are not modeled.</p><p class="small-copy">Requires 96 QC-passed samples spanning 48h and 48 sufficiently close pairs. Missing data or invalid origins block simulation. Suspect readings are not silently replaced with last_good; future data is never used for fitting.</p><p class="annotation">The source spans about 14 days; simulation does not outperform persistence for every parameter. Do not use it for automatic control, disease diagnosis or water-quality guarantees.</p>`)}
const renderBeforeLongForecast=render;
render=function(){if(active==='forecast'){if(forecastResult?.ok&&forecastResult.inputSnapshotId!==row().id)forecastResult=null;$('#breadcrumb').textContent='1–2 day simulation forecast';$('#page').innerHTML=forecastPage();problemNav();bind();$('#longForecastKey').onchange=e=>{forecastKey=e.target.value;forecastRate=0;forecastResult=null;forecastEvaluation=null;render()};$('#longForecastHours').onchange=e=>{forecastHours=Number(e.target.value);forecastResult=null;render()};$('#longForecastForm').onsubmit=e=>{e.preventDefault();forecastRate=Number($('#longForecastRate').value);forecastAllowSuspect=$('#longForecastAllow').checked;forecastResult=WaterForecast.simulate(data,cursor,forecastKey,{hours:forecastHours,ratePerDay:forecastRate,allowSuspect:forecastAllowSuspect});render()};$('#evaluateLongForecast').onclick=()=>{forecastEvaluation=evaluationCache[forecastKey]||(evaluationCache[forecastKey]=WaterForecast.evaluate(data,forecastKey));render()};$('#exportLongForecast')?.addEventListener('click',()=>download('aquatwin-simulation-'+forecastKey+'-'+forecastHours+'h.json',JSON.stringify(forecastResult,null,2),'application/json'));return}renderBeforeLongForecast();if(active==='overview'){const b=document.createElement('button');b.className='button';b.textContent='▷ 1–2 day simulation forecast';b.onclick=()=>{forecastResult=null;location.hash='forecast'};$('.heading-buttons')?.prepend(b)}const key=problemKey();if(problems[key]){const title=[...document.querySelectorAll('.card h2')].find(h=>h.textContent==='2. Reference forecast');if(title){title.textContent='2. 24–48 hour forecast';const card=title.closest('.card');const head=card.querySelector('.card-head');while(head.nextSibling)head.nextSibling.remove();card.insertAdjacentHTML('beforeend','<p class="small-copy">Simulate 1–2 day trajectories from the snapshot and past data, with a baseline, additional scenario trends and historical error evaluation.</p><button class="button full-width" id="openProblemForecast">▷ Open simulation forecast</button>');$('#openProblemForecast').onclick=()=>{forecastKey=key;forecastResult=null;forecastEvaluation=null;forecastRate=0;location.hash='forecast'}}}};
